import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    inf = 10**18
    potential = [inf] * n
    potential[0] = 0
    for u in range(n):
        if potential[u] >= inf:
            continue
        for to, cap, cost, _rev in graph[u]:
            if cap and potential[to] > potential[u] + cost:
                potential[to] = potential[u] + cost

    sink = n - 1
    flow = 0
    total_cost = 0
    while flow < k:
        dist = [inf] * n
        dist[0] = 0
        parent = [(-1, -1)] * n
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for ei, (to, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                nd = d + cost + potential[u] - potential[to]
                if nd < dist[to]:
                    dist[to] = nd
                    parent[to] = (u, ei)
                    heapq.heappush(heap, (nd, to))
        if dist[sink] >= inf:
            break
        for i in range(n):
            if dist[i] < inf:
                potential[i] += dist[i]
        add = k - flow
        v = sink
        while v != 0:
            u, ei = parent[v]
            add = min(add, graph[u][ei][1])
            v = u
        v = sink
        while v != 0:
            u, ei = parent[v]
            graph[u][ei][1] -= add
            rev = graph[u][ei][3]
            graph[v][rev][1] += add
            total_cost += add * graph[u][ei][2]
            v = u
        flow += add
    return -total_cost
